        "Çoğulu: die Äußerlichkeiten. Sözcük genellikle eleştirel bir anlamda kullanılır: Er achtet nur auf Äußerlichkeiten (yalnızca dış görünüşe önem veriyor).",
        "Sözcük äußerlich (dışsal) sıfatından türemiştir; die Äußerlichkeit ismi yalnızca dışta olanı, derinliği olmayanı anlatır."
