        "Fanatik bir tutku için de kullanılır: von der Arbeit besessen sein, wie besessen arbeiten (deli gibi çalışmak).",
        "Dikkat: besessen aynı zamanda besitzen (sahip olmak) fiilinin ortacıdır: Er hat ein Haus besessen. Bu başka bir kullanımdır; bu kart takıntılı anlamındaki sıfatla ilgilidir."
