        "Dönüşlü fiil: ich verlaufe mich, er verläuft sich, verlief sich, hat sich verlaufen. Perfekt için haben kullanılır. Genellikle bir yer bildirimiyle birlikte kullanılır: im Wald, in der Stadt, in den Bergen.",
        "Taşıtla yolunu kaybedersen sich verfahren denir; sich verirren daha geneldir ve yolunu şaşırıp kaybolmak anlamında da kullanılabilir."
